"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[4188],{13858(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>r,default:()=>h,frontMatter:()=>a,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"general/checklists-can-avoid-it-disasters","title":"Checklists Can Avoid It Disasters","description":"By JCDavid","source":"@site/docs/general/checklists-can-avoid-it-disasters.md","sourceDirName":"general","slug":"/general/checklists-can-avoid-it-disasters","permalink":"/jc-community-archive/general/checklists-can-avoid-it-disasters","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Checklists Can Avoid It Disasters","description":"By JCDavid"},"sidebar":"docs","previous":{"title":"Check Out The New Powershell Courses In Jcu","permalink":"/jc-community-archive/general/check-out-the-new-powershell-courses-in-jcu"},"next":{"title":"Chrome Extension For App Quick Access","permalink":"/jc-community-archive/general/chrome-extension-for-app-quick-access"}}');var s=n(74848),o=n(28453);const a={title:"Checklists Can Avoid It Disasters",description:"By JCDavid"},r=void 0,c={},l=[];function d(e){const t={a:"a",li:"li",p:"p",ul:"ul",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.p,{children:"Many IT departments function along the lines of, \"I've got that,' where somebody who's experienced in tech \"does their thing.\" That works, until your organization grows and can no longer function without formal processes. It's a difficult transition and not everyone will be on board with it. You'll require the right team members, doing the appropriate things. Checklists are important activity that will assist with ensuring IT quality through documenting solutions and documenting what happened (and when)."}),"\n",(0,s.jsxs)(t.p,{children:["My previous company was able to operate by the seat of its pants, but process change and well-defined roles became necessary over time. For instance, an IT admin loved to solve problems and quickly responded to complaints from accounting that the ERP system wasn't emailing invoices to customers after we'd migrated from Exchange to M365. Accounts Receivable is an important corporate function, so he was correct to ",(0,s.jsx)(t.a,{href:"https://jumpcloud.com/blog/how-to-use-an-it-priority-matrix",children:"prioritize"})," that problem (plus nobody messed with Edna in accounting ... haha just kidding, Edna)."]}),"\n",(0,s.jsx)(t.p,{children:"However, his response was seat of the pants: setting up an SMTP server in Windows Server as a bridge. It worked, but he didn't think through the solution and external parties began using it also. Guess what happened next? Our IPs were blacklisted, so legitimate email invoices ended up in customers' spam inboxes. There was also the potential exposure of our systems to the open web to consider."}),"\n",(0,s.jsx)(t.p,{children:"It was a parade of \"terribles\" that interfered with our cashflow and aggravated accounting over a week or so. They lost trust in the IT department and we lost credibility. That's where checklists come in. Taking a little more time to document a well-defined solution would have avoided that difficulty. IT people sometimes *hate* taking the time to create and maintain checklists, but it's important for several practical reasons."}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsx)(t.li,{children:"Keeping auditors happy if you're dealing with compliance (ISO in my case)"}),"\n",(0,s.jsx)(t.li,{children:"Making it easier to onboard new team members"}),"\n",(0,s.jsx)(t.li,{children:"Overall quality and metrics that an IT director can examine to understand what's going on within their organization"}),"\n",(0,s.jsx)(t.li,{children:'Avoiding the "too smart for my own good" IT guru solution discussed above'}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"It's ideal to have a small team of rockstars that just solves problems, but maturing organizations can't accept that level of risk. The lesson I learned was not to place too much trust into individuals, even if they're \"awesome.\" My advice is to skate to where the puck is going next and begin to produce checklists, even before your organization grows. It's not micromanagement, it's process."})]})}function h(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var i=n(96540);const s={},o=i.createContext(s);function a(e){const t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);